@router.post("/{item_id}/restock")
@require_role("staff")
def restock_item(request: Request, item_id: str) -> Response:
    amount = parse_positive_int(request.query.get("amount"), default=1, maximum=1000)
    db.execute("UPDATE items SET quantity = quantity + ? WHERE id = ?", (amount, int(item_id)))
    return Response(status=204)

@router.get("/{item_id}")
@require_login
def get_item(request: Request, item_id: str) -> Response:
    row = db.query_one("SELECT id, name, price, quantity FROM items WHERE id = ?", (int(item_id),))
    if row is None:
        raise HTTPError(404, "item not found")
    return Response.json(dict(row))

def calculate_total(lines: list[OrderLine], tax_rate: Decimal, discount: Decimal) -> Decimal:
    """Return the order total including tax, rounded to cents.

    `discount` is a fraction in [0, 1) taken off the subtotal before tax.
    """
    if not Decimal("0") <= discount < Decimal("1"):
        raise ValueError("discount must be in [0, 1)")
    subtotal = sum((line.unit_price * line.quantity for line in lines), Decimal("0"))
    discounted = subtotal * (1 - discount)
    return (discounted * (1 + tax_rate)).quantize(CENT)

